send_cors_headers();$context=require_vendor(true);$vendorId=$context['vendor']['id'];$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';
if($method==='GET'){$groupId=trim((string)($_GET['group_id']??''));$stmt=$db->prepare('SELECT c.*,g.group_number,g.status AS group_status,o.order_number FROM cod_collections c JOIN vendor_order_groups g ON g.id=c.vendor_group_id JOIN orders o ON o.id=c.order_id WHERE c.vendor_id=:vendor AND (:group="" OR c.vendor_group_id=:group) ORDER BY c.created_at DESC');$stmt->execute(['vendor'=>$vendorId,'group'=>$groupId]);json_response(200,['success'=>true,'collections'=>$stmt->fetchAll()]);}
if($method==='POST'){$body=get_json_body();$groupId=trim((string)($body['group_id']??''));$status=trim((string)($body['status']??''));$methodName=trim((string)($body['collection_method']??''));$reference=trim((string)($body['collection_reference']??''));$amount=round((float)($body['amount']??0),2);if(!in_array($status,['collected','failed'],true)||!in_array($methodName,['cash','upi','card','bank_transfer'],true)||mb_strlen($reference)<3)json_response(422,['success'=>false,'message'=>'Collection status, method and reference are required.']);$db->beginTransaction();try{$stmt=$db->prepare('SELECT g.*,o.payment_status,o.user_id,o.order_number FROM vendor_order_groups g JOIN orders o ON o.id=g.order_id WHERE g.id=:group AND g.vendor_id=:vendor FOR UPDATE');$stmt->execute(['group'=>$groupId,'vendor'=>$vendorId]);$group=$stmt->fetch();if(!$group)json_response(404,['success'=>false,'message'=>'Vendor order group not found.']);if($group['status']!=='delivered')json_response(409,['success'=>false,'message'=>'Cash can be reconciled only after the package is delivered.']);if($status==='collected'&&abs($amount-(float)$group['total_amount'])>0.01)json_response(422,['success'=>false,'message'=>'Collected amount must exactly match the vendor order total.']);$existing=$db->prepare('SELECT * FROM cod_collections WHERE vendor_group_id=:group FOR UPDATE');$existing->execute(['group'=>$groupId]);$collection=$existing->fetch();if($collection&&$collection['status']==='collected')json_response(409,['success'=>false,'message'=>'Cash collection is already reconciled.']);$collectionId=$collection['id']??uuid_string();$db->prepare('INSERT INTO cod_collections (id,order_id,vendor_group_id,vendor_id,amount,status,collection_method,collection_reference,collected_by_type,collected_by_id,collected_at,failure_reason,created_at,updated_at) VALUES (:id,:order,:group,:vendor,:amount,:status,:method,:reference,\"vendor\",:actor,IF(:status=\"collected\",UTC_TIMESTAMP(),NULL),IF(:status=\"failed\",:reason,NULL),COALESCE((SELECT created_at FROM cod_collections WHERE id=:existing),UTC_TIMESTAMP()),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE amount=VALUES(amount),status=VALUES(status),collection_method=VALUES(collection_method),collection_reference=VALUES(collection_reference),collected_by_type=VALUES(collected_by_type),collected_by_id=VALUES(collected_by_id),collected_at=VALUES(collected_at),failure_reason=VALUES(failure_reason),updated_at=UTC_TIMESTAMP()')->execute(['id'=>$collectionId,'order'=>$group['order_id'],'group'=>$groupId,'vendor'=>$vendorId,'amount'=>$amount,'status'=>$status,'method'=>$methodName,'reference'=>$reference,'actor'=>$vendorId,'reason'=>$body['failure_reason']??null,'existing'=>$collectionId]);if($status==='collected'){$db->prepare('UPDATE vendor_ledger_entries le JOIN order_items oi ON le.reference_type=\"order_item\" AND le.reference_id=CAST(oi.id AS CHAR) SET le.balance_bucket=\"eligible\",le.available_at=UTC_TIMESTAMP() WHERE oi.vendor_group_id=:group AND le.balance_bucket=\"pending\"')->execute(['group'=>$groupId]);$all=$db->prepare('SELECT COUNT(*) total,SUM(status=\"collected\") collected FROM cod_collections WHERE order_id=:order FOR UPDATE');$all->execute(['order'=>$group['order_id']]);$counts=$all->fetch();if((int)$counts['total']>0&&(int)$counts['total']===(int)$counts['collected'])$db->prepare('UPDATE orders SET payment_status=\"paid\",updated_at=UTC_TIMESTAMP() WHERE id=:id AND payment_status=\"cod_pending\"')->execute(['id'=>$group['order_id']]);}create_notification('customer',$group['user_id'],'cod_update','Cash on delivery update',$status==='collected'?'Cash on delivery was confirmed for your order.':'Cash collection could not be reconciled for this delivery.','../orders.php',['order_id'=>$group['order_id'],'group_id'=>$groupId]);audit_event('vendor.cod_'.$status,'cod_collection',$collectionId,['group_id'=>$groupId,'amount'=>$amount,'reference'=>$reference]);$db->commit();json_response(200,['success'=>true,'message'=>$status==='collected'?'Cash collection reconciled.':'Cash collection marked failed.','status'=>$status]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
